def dict_depth(d):
    """Write a function to find the depth of a dictionary.

    The depth is the maximum number of nested dictionaries.
    An empty or flat dictionary has depth 1, as in the example
    where ``{'d': {}}`` contributes two levels. Non-dictionary
    values do not increase the depth, and a non-dictionary
    argument has depth 0.
    """
    if not isinstance(d, dict):
        return 0
    max_depth = 0
    stack = [(d, 1)]
    while stack:
        node, depth = stack.pop()
        if depth > max_depth:
            max_depth = depth
        for value in node.values():
            if isinstance(value, dict):
                stack.append((value, depth + 1))
    return max_depth
